body.script:
(() => {
  'use strict';
  const rtlRegex = /[\u0780-\u07BF\u0600-\u06FF]/;
  document.querySelectorAll('.self-detect').forEach(article => {
    const text = article.innerText || '';
    if (rtlRegex.test(text)) {
      article.setAttribute('data-dir', 'rtl');
    } else {
      article.setAttribute('data-dir', 'ltr');
    }
  });
})();
